//! 🧪️ The real original action factory constructs one typed command and its exact borrowed Pack wire.
use super::*;
use semio_framework_job::{OriginalJobFixtureCaller,OriginalJobDecodeOwner,OperationId,Generation,default_now_us};
use semio_framework_dsl_record::{BorrowedRecordSpec as R,BorrowedFieldSpec as F,BorrowedShape as S,RecordLayout,native_encoding::{FieldProjectionSource,FieldProjectionView as V}};
use semio_framework_value::RetainedCloneGrant;
#[derive(semio_framework_value::RetireOwned)]struct Command{kind:String,text:String}
impl FieldProjectionSource for Command{fn projection_view(&self,path:&[usize])->Result<V<'_>,ValueError>{match path{[]=>Ok(V::Record(&[1,2])),[0]=>Ok(V::Text(&self.kind)),[1]=>Ok(V::Text(&self.text)),_=>Err(invalid())}}}
impl EnergyOriginalCommand<String> for Command{
 fn descriptor(index:usize)->Option<(&'static str,&'static str,NativeActionFactory<String>)>{match index{0=>Some(("OtherAction","other",NativeActionFactory::of::<String>())),1=>Some(("RenameModel","rename-model",NativeActionFactory::of::<String>())),_=>None}}
 fn from_original_mutation(kind:String,text:String)->Self{Self{kind,text}}
 fn original_wire(&self)->ArtifactPreparedOperationSource<'_>{const FIELDS:&[F]=&[F::new(1,"kind",S::Text),F::new(2,"text",S::Text)];ArtifactPreparedOperationSource::Pack{tag:3,body:self,spec:R{keyword:None,layout:RecordLayout::Inline,fields:FIELDS}}}
 const MAXIMUM_WIRE_BYTES:usize=262144;
}
const G:RetainedCloneGrant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:32768,maximum_capacity_bytes:1<<24,maximum_release_bytes:1<<24,maximum_depth:4096};
fn event<R>(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,g:RetainedCloneGrant,run:impl FnOnce(&mut StepContext<'_>)->Result<R,OriginalTurnFailure>)->R{let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(g,decoder,run));let p=caller.receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes),"original Energy command physical receipt {p:?}; failure={:?}",result.as_ref().err());result.unwrap()}
fn denied(d:RetirementDemand,axis:usize)->Option<RetainedCloneGrant>{let mut g=G;match axis{0=>g.maximum_items=0,1 if d.copy_bytes>0=>g.maximum_copy_bytes=d.copy_bytes-1,2 if d.capacity_bytes>0=>g.maximum_capacity_bytes=d.capacity_bytes-1,3 if d.release_bytes>0=>g.maximum_release_bytes=d.release_bytes-1,4 if d.depth>0=>g.maximum_depth=d.depth-1,_=>return None};Some(g)}
fn varint(mut value:usize,output:&mut Vec<u8>){loop{let byte=(value&127)as u8;value>>=7;output.push(byte|if value==0{0}else{128});if value==0{break}}}
#[test]fn original_energy_command_factory_retains_the_same_arguments_command_and_wire_until_handoff(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let factory=EnergyActionFactory::<Command,String>::new();
 for cut in law["cancelPrefixes"].as_array().unwrap().iter().map(|v|Some(v.as_u64().unwrap()as usize)).chain([None]){
  let text=law["text"].as_str().unwrap().repeat(law["repeat"].as_u64().unwrap()as usize);let oracle:serde_json::Value=serde_json::from_str(&serde_json::to_string(&text).unwrap()).unwrap();let mut args=Some(DslValue::String(text));let pointer=args.as_ref().unwrap().as_str().unwrap().as_ptr();let mut fault=None;let mut owner=None;let mut caller=OriginalJobFixtureCaller::admit(OperationId(483),Generation(2),RetainedCloneGrant{maximum_items:1<<30,maximum_copy_bytes:1<<30,maximum_capacity_bytes:1<<29,maximum_release_bytes:1<<29,maximum_depth:4096},default_now_us,u64::MAX,1<<30);let mut decoder=OriginalJobDecodeOwner::empty();let action=law["action"].as_str().unwrap();let d=factory.birth_demands().unwrap();
  for axis in 0..5{let Some(g)=denied(d,axis)else{continue};assert!(!event(&mut caller,&mut decoder,g,|cx|factory.admit(cx,&mut owner)));assert!(owner.is_none());assert_eq!(args.as_ref().unwrap().as_str().unwrap().as_ptr(),pointer);}
  assert!(event(&mut caller,&mut decoder,G,|cx|factory.admit(cx,&mut owner)));let frame_bytes=d.capacity_bytes;
  let mut foreign=OriginalJobDecodeOwner::empty();event(&mut caller,&mut foreign,G,|cx|{assert!(owner.as_mut().unwrap().advance(action,&mut args,&mut fault,cx).is_err());Ok(())});assert!(foreign.terminal_is_empty());
  for index in 0..262144{if cut==Some(index){break}if owner.as_ref().unwrap().ready(){break}let d=owner.as_ref().unwrap().demands(action,&args,&fault,G.maximum_copy_bytes).unwrap();assert!(d.copy_bytes<=G.maximum_copy_bytes,"actual command source quote exceeds admitted body {d:?}");for axis in 0..5{let Some(g)=denied(d,axis)else{continue};event(&mut caller,&mut decoder,g,|cx|owner.as_mut().unwrap().advance(action,&mut args,&mut fault,cx));assert_eq!(caller.receipt(),Default::default());assert_eq!(owner.as_ref().unwrap().demands(action,&args,&fault,G.maximum_copy_bytes).unwrap(),d);}event(&mut caller,&mut decoder,G,|cx|owner.as_mut().unwrap().advance(action,&mut args,&mut fault,cx));assert!(index<262143,"Energy command source stalled {d:?}");}
  let mut command=None;let mut wire=None;if cut.is_none(){let d=owner.as_ref().unwrap().take_demands().unwrap();for axis in 0..5{let Some(g)=denied(d,axis)else{continue};assert!(!event(&mut caller,&mut decoder,g,|cx|owner.as_mut().unwrap().take_into(&mut command,&mut wire,cx)));assert!(command.is_none()&&wire.is_none());}assert!(event(&mut caller,&mut decoder,G,|cx|owner.as_mut().unwrap().take_into(&mut command,&mut wire,cx)));let actual=command.as_ref().unwrap();assert_eq!(actual.kind,law["kind"].as_str().unwrap());assert_eq!(actual.text,oracle.as_str().unwrap());let mut expected=vec![1,3,1];varint(actual.kind.len(),&mut expected);expected.extend_from_slice(actual.kind.as_bytes());expected.extend_from_slice(&[2,1,6,0,2,7]);varint(actual.text.len(),&mut expected);expected.extend_from_slice(actual.text.as_bytes());let mut bytes=0;for rank in 0..wire.as_ref().unwrap().page_count(){let page=wire.as_ref().unwrap().page(rank).unwrap();assert!(page==&expected[bytes..bytes+page.len()],"native command Pack differs from authored dictionary/field wire at page offset {bytes}");bytes+=page.len();}assert_eq!(bytes,expected.len());}else{caller.cancel().cancel_now();}
  for index in 0..262144{if owner.as_ref().unwrap().terminal_is_empty(){break}let d=owner.as_ref().unwrap().close_demands(G.maximum_copy_bytes).unwrap();for axis in 0..5{let Some(g)=denied(d,axis)else{continue};event(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|owner.as_mut().unwrap().close_step(cx)));assert_eq!(caller.receipt(),Default::default());assert_eq!(owner.as_ref().unwrap().close_demands(G.maximum_copy_bytes).unwrap(),d);}event(&mut caller,&mut decoder,G,|cx|cx.with_original_retirement(|cx|owner.as_mut().unwrap().close_step(cx)));assert!(index<262143,"original Energy command cancellation stalled {d:?}");}
  event(&mut caller,&mut decoder,G,|cx|cx.with_original_retirement(|cx|{let d=RetirementDemand{release_bytes:frame_bytes,depth:1,..Default::default()};close_original_retained_step(cx,d,|_|{owner.take();Ok(RetainedCloneStep::Complete(receipt(d)))})?;Ok(())}));
  let mut close=RetainedCloneClose::default();for index in 0..262144{if args.is_none()&&command.is_none()&&wire.is_none()&&close.is_empty(){break}event(&mut caller,&mut decoder,G,|cx|cx.with_original_retirement(|cx|{let d=if !close.is_empty(){close.demands(G.maximum_copy_bytes)?}else if args.is_some(){close.next_owner_demands::<DslValue>(true,&None,G.maximum_copy_bytes)?}else if command.is_some(){close.next_owner_demands::<Box<Command>>(true,&None,G.maximum_copy_bytes)?}else{close.next_owner_demands::<RetainedToolWireInput>(true,&None,G.maximum_copy_bytes)?};close_original_retained_step(cx,d,|g|if !close.is_empty(){close.select(G.maximum_copy_bytes)?.step(g)}else if args.is_some(){Ok(close.begin_granted(&mut args,g)?.unwrap())}else if command.is_some(){Ok(close.begin_granted(&mut command,g)?.unwrap())}else{Ok(close.begin_granted(&mut wire,g)?.unwrap())})?;Ok(())}));assert!(index<262143);}
  while !decoder.terminal_is_empty(){caller.turn(G,|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(G.maximum_copy_bytes)?;close_original_retained_step(cx,d,|g|decoder.close_step(g))?;Ok(())})).unwrap();}caller.retire(G);
 }
}
